func EmitBodySchema(w io.Writer, operationID string) error {
	schema, ok := bodySchemas[operationID]
	if !ok {
		return fmt.Errorf("no request body schema for %s", operationID)
	}
	_, err := fmt.Fprintln(w, schema)
	return err
}
